using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(int subtotalCents, LoyaltyTier tier)
    {
        var ratePoints = Math.Min(BaseRatePoints(tier) + SizeBonusPoints(subtotalCents), MaxRatePoints);
        var discountCents = (int)((long)subtotalCents * ratePoints / 100);

        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unapproved loyalty tier.")
    };

    private static int SizeBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
